import { Order } from './types';

function compare(a: Order, b: Order): number {
  return a.createdAt < b.createdAt ? -1 : a.createdAt > b.createdAt ? 1 : a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}

  /** All orders of the tenant, sorted ascending by createdAt then id. Does not mutate stored rows. */
  list(tenant: string): Order[] {
    return this.rows.filter(row => row.tenant === tenant).sort(compare);
  }

  /**
   * Orders of the tenant strictly after the (createdAt, id) pair `after` (if given),
   * sorted ascending, at most `limit` items. `hasMore` tells whether further matching orders exist.
   * Tenant filtering happens before the cursor is applied.
   */
  listPage(
    tenant: string,
    limit: number,
    after?: { createdAt: string; id: string }
  ): { items: Order[]; hasMore: boolean } {
    const matching = this.list(tenant).filter(
      row =>
        !after ||
        row.createdAt > after.createdAt ||
        (row.createdAt === after.createdAt && row.id > after.id)
    );
    return { items: matching.slice(0, limit), hasMore: matching.length > limit };
  }
}
